{"t":"say","text":"I'll draw a multi-node training pipeline in Frankfurt with Lingjun and CPFS, then serve the 30B model via PAI-EAS."}
{"t":"req","text":"Training data must stay in Frankfurt","regions":["eu-central-1"]}
{"t":"plan","products":["oss","pai-dlc","lingjun","cpfs","pai-eas","ai-gateway","alb","nat","sls"]}
{"t":"assume","id":"weights","text":"You keep your own tuned weights, so we use PAI, not Model Studio","alt":"Light SFT of Qwen on hosted Model Studio (no weight export)"}
{"t":"group","id":"frankfurt","kind":"region","label":"Frankfurt (eu-central-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"AI VPC","parent":"frankfurt"}
{"t":"node","id":"oss","product":"oss","label":"Training data & checkpoints","group":"frankfurt","why":"Stores datasets and model checkpoints; data stays in Frankfurt."}
{"t":"node","id":"training","product":"pai-dlc","label":"Distributed training jobs","group":"frankfurt","why":"Orchestrates multi-node 30B fine-tuning across GPUs."}
{"t":"edge","id":"e-training-oss","from":"training","to":"oss","label":"data"}
{"t":"node","id":"lingjun","product":"lingjun","label":"Lingjun GPU cluster","group":"vpc","why":"Bare-metal GPUs with RDMA for fast multi-node training."}
{"t":"edge","id":"e-training-lingjun","from":"training","to":"lingjun","kind":"control"}
{"t":"node","id":"cpfs","product":"cpfs","label":"Parallel file storage","group":"vpc","why":"High-throughput shared storage for training data across nodes."}
{"t":"edge","id":"e-lingjun-cpfs","from":"lingjun","to":"cpfs","label":"RDMA"}
{"t":"say","text":"After training, the model is deployed to PAI-EAS behind an AI Gateway for serving."}
{"t":"node","id":"serving","product":"pai-eas","label":"30B model serving","group":"vpc","why":"Hosts the trained 30B model for online inference."}
{"t":"edge","id":"e-training-serving","from":"training","to":"serving","label":"deploy","kind":"control"}
{"t":"node","id":"gateway","product":"ai-gateway","label":"AI Gateway","group":"vpc","why":"Routes requests, enforces token limits and fallbacks."}
{"t":"edge","id":"e-gateway-serving","from":"gateway","to":"serving","label":"private endpoint"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Exposes the AI gateway over HTTPS in two zones."}
{"t":"edge","id":"e-alb-gateway","from":"alb","to":"gateway"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Outbound access for dependencies or external APIs."}
{"t":"edge","id":"e-serving-nat","from":"serving","to":"nat","kind":"control"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"frankfurt","why":"Collects training and serving logs for observability."}
{"t":"edge","id":"e-training-logs","from":"training","to":"logs","kind":"control"}
{"t":"edge","id":"e-serving-logs","from":"serving","to":"logs","kind":"control"}
{"t":"ask","id":"access","text":"Who calls the serving endpoint?","options":["Public internet users","Internal apps only"]}
{"t":"ask","id":"gpu-scale","text":"How many GPU nodes do you expect for training?","options":["2–4 nodes","8+ nodes"]}
{"t":"done","summary":"Frankfurt-only 30B model pipeline: PAI-DLC on Lingjun with CPFS for training, PAI-EAS behind AI Gateway and ALB for serving."}

{"t":"say","text":"I'll draw a self-hosted Qwen serving architecture on PAI-EAS behind an AI Gateway for token quotas, routing and failover."}
{"t":"plan","products":["users","alb","ai-gateway","pai-eas","nat","sls","prometheus"]}
{"t":"req","text":"Internal users only, Singapore region","regions":["ap-southeast-1"]}
{"t":"assume","id":"vpc-access","text":"Users reach the VPC over private network or VPN","alt":"Public ALB with IP allowlist"}
{"t":"group","id":"internal","kind":"external","label":"Internal network","parent":null}
{"t":"node","id":"users","product":"users","label":"Internal users (2k concurrent)","group":"internal","why":"About 2,000 internal staff across teams calling the model."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"AI VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"Internal ALB","group":"vpc","zones":["a","b"],"why":"Private load balancer distributing traffic to AI Gateway replicas."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"private"}
{"t":"node","id":"gw","product":"ai-gateway","label":"AI Gateway","group":"vpc","zones":["a","b"],"why":"Per-team token quotas, multi-model routing and failover policies."}
{"t":"edge","id":"e-alb-gw","from":"alb","to":"gw"}
{"t":"node","id":"llm-a","product":"pai-eas","label":"Qwen primary (zone A)","group":"vpc","zones":["a"],"why":"Primary dedicated GPU endpoint serving the large Qwen model."}
{"t":"node","id":"llm-b","product":"pai-eas","label":"Qwen standby (zone B)","group":"vpc","zones":["b"],"why":"Standby endpoint in zone B for failover when primary is down."}
{"t":"edge","id":"e-gw-llm-a","from":"gw","to":"llm-a","label":"primary"}
{"t":"edge","id":"e-gw-llm-b","from":"gw","to":"llm-b","label":"failover"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Outbound internet for PAI-EAS to pull images or call APIs."}
{"t":"edge","id":"e-llm-a-nat","from":"llm-a","to":"nat","kind":"control"}
{"t":"edge","id":"e-llm-b-nat","from":"llm-b","to":"nat","kind":"control"}
{"t":"say","text":"Adding observability: SLS for logs and Prometheus for GPU and latency metrics."}
{"t":"node","id":"logs","product":"sls","label":"Log Service","group":"sg","why":"Centralizes gateway and model serving logs for audit and debugging."}
{"t":"edge","id":"e-gw-logs","from":"gw","to":"logs","kind":"control"}
{"t":"node","id":"metrics","product":"prometheus","label":"Managed Prometheus","group":"sg","why":"Monitors GPU utilization, token throughput and endpoint health."}
{"t":"edge","id":"e-gw-metrics","from":"gw","to":"metrics","kind":"control"}
{"t":"ask","id":"model-size","text":"Which Qwen size are you targeting? This determines GPU count and whether one node per zone suffices.","options":["72B (multi-GPU)","32B (single or few GPUs)","14B or smaller"]}
{"t":"ask","id":"failover-mode","text":"Should the standby be warm (always running, higher cost) or cold (auto-scale from zero on failover)?","options":["Warm standby","Cold start on failover"]}
{"t":"done","summary":"Self-hosted Qwen on two PAI-EAS endpoints behind AI Gateway for per-team quotas and failover, fronted by an internal ALB."}

{"t":"say","text":"我将为您设计一个基于 PAI-EAS 的私有知识库问答系统，向量数据和模型均部署在 VPC 内网。"}
{"t":"plan","products":["users","dns","alb","waf","ecs","pai-eas","elasticsearch","oss","nat","model-studio","sls"]}
{"t":"assume","id":"scale","text":"约100名内部员工使用","alt":"超过1000名员工并发访问"}
{"t":"assume","id":"embedding","text":"Embedding调用托管Qwen API","alt":"在PAI-EAS上自托管Embedding模型"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"内部用户","group":"internet","why":"通过浏览器访问知识库问答系统的企业员工。"}
{"t":"node","id":"dns","product":"dns","label":"云解析DNS","group":null,"why":"将问答系统域名解析到负载均衡入口。"}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"作为问答系统前端入口，跨可用区分发流量。"}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"保护问答接口免受注入和CC攻击。"}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"app","product":"ecs","label":"RAG应用服务","group":"vpc","zones":["a","b"],"why":"运行RAG编排逻辑，处理文档分块、检索与提示词组装。"}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"node","id":"rag-service","product":"pai-eas","label":"RAG服务","group":"vpc","zones":["a","b"],"why":"提供RAG检索与推理API，承载自定义Qwen模型权重。"}
{"t":"edge","id":"e-app-rag","from":"app","to":"rag-service","label":"private endpoint"}
{"t":"node","id":"llm","product":"pai-eas","label":"Qwen LLM","group":"vpc","zones":["a","b"],"why":"专属GPU实例部署自有的Qwen模型，用于最终答案生成。"}
{"t":"edge","id":"e-rag-llm","from":"rag-service","to":"llm","label":"inference"}
{"t":"node","id":"vector-db","product":"elasticsearch","label":"Elasticsearch向量库","group":"vpc","zones":["a","b"],"why":"存储文档向量数据，支持混合检索，完全保留在VPC内网。"}
{"t":"edge","id":"e-rag-vector","from":"rag-service","to":"vector-db","label":"search"}
{"t":"node","id":"docs","product":"oss","label":"文档存储","group":"sg","why":"存放企业内部原始文档供RAG应用读取和向量化。"}
{"t":"edge","id":"e-app-docs","from":"app","to":"docs","label":"read docs"}
{"t":"node","id":"nat","product":"nat","label":"NAT网关","group":"vpc","why":"为VPC内的ECS和PAI-EAS提供出站公网访问能力。"}
{"t":"edge","id":"e-rag-nat","from":"rag-service","to":"nat","kind":"control"}
{"t":"node","id":"model-api","product":"model-studio","label":"Model Studio","group":"sg","why":"提供托管Embedding API，用于将文档转换为向量。"}
{"t":"edge","id":"e-nat-model","from":"nat","to":"model-api","label":"embeddings"}
{"t":"node","id":"logs","product":"sls","label":"日志服务","group":"sg","why":"集中收集RAG应用和PAI-EAS的运行日志与审计记录。"}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"ask","id":"embedding-method","text":"文档向量化（Embedding）希望如何完成？","options":["调用Model Studio托管API","在PAI-EAS自建Embedding模型"]}
{"t":"ask","id":"user-auth","text":"内部用户登录认证方式是什么？","options":["IDaaS单点登录","企业自有LDAP/AD","无需复杂认证"]}
{"t":"done","summary":"基于PAI-EAS部署自有Qwen模型的RAG架构，Elasticsearch向量库与模型推理均在VPC内网，通过NAT调用外部Embedding API。"}

{"t":"say","text":"I'll draw a custom agentic RL post-training design: PAI-DLC for training calling Agent Sandbox for thousands of rollouts. This has no official Alibaba Cloud reference; the nearest documented pattern is ACK plus VeRL."}
{"t":"plan","products":["pai-dlc","agent-sandbox","oss","cpfs"]}
{"t":"assume","id":"rl-framework","text":"Custom RL framework on PAI-DLC","alt":"VeRL on ACK"}
{"t":"assume","id":"model-size","text":"Model fits single-node GPU","alt":"Multi-node Lingjun cluster"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"node","id":"trainer","product":"pai-dlc","label":"RL Training Jobs","group":"sg","why":"Runs RL post-training jobs that orchestrate rollout requests to sandboxes."}
{"t":"node","id":"sandbox","product":"agent-sandbox","label":"Rollout Sandboxes","group":"sg","why":"E2B-compatible managed sandboxes created by API for thousands of short-lived rollouts."}
{"t":"edge","id":"e-trainer-sandbox","from":"trainer","to":"sandbox","label":"rollouts","kind":"async"}
{"t":"node","id":"artifacts","product":"oss","label":"Checkpoints and Data","group":"sg","why":"Stores model checkpoints, datasets and rollout logs."}
{"t":"edge","id":"e-trainer-artifacts","from":"trainer","to":"artifacts","label":"read/write","kind":"data"}
{"t":"ask","id":"rl-stack","text":"Which RL stack are you using?","options":["VeRL","OpenRLHF","Custom framework"]}
{"t":"ask","id":"scale","text":"How many concurrent rollouts do you target?","options":["~1,000","~10,000","Over 50,000"]}
{"t":"done","summary":"Custom agentic RL post-training in Singapore with PAI-DLC orchestrating thousands of Agent Sandbox rollouts, storing artifacts in OSS."}

{"t":"say","text":"PAI-LangStudio isn't in the current catalog, so I'll build your document Q&A agent using PAI-EAS, Model Studio and Milvus."}
{"t":"plan","products":["users","dns","alb","pai-eas","model-studio","milvus","oss","nat"]}
{"t":"assume","id":"exposure","text":"Internal users only","alt":"Public-facing app"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Users","group":"internet","why":"People asking questions about documents."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the agent domain to ALB."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Agent VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Routes user requests to the RAG service."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"rag","product":"pai-eas","label":"RAG service","group":"vpc","zones":["a","b"],"why":"Serves the Q&A logic, retrieves context and calls LLM."}
{"t":"edge","id":"e-alb-rag","from":"alb","to":"rag"}
{"t":"node","id":"llm","product":"model-studio","label":"Model Studio","group":"sg","why":"Hosted Qwen model generates answers from retrieved context."}
{"t":"edge","id":"e-rag-llm","from":"rag","to":"llm","label":"LLM API"}
{"t":"node","id":"vector","product":"milvus","label":"Milvus","group":"vpc","zones":["a","b"],"why":"Stores document embeddings for semantic retrieval."}
{"t":"edge","id":"e-rag-vector","from":"rag","to":"vector","label":"search"}
{"t":"node","id":"docs","product":"oss","label":"Documents","group":"sg","why":"Holds source files for ingestion into the vector store."}
{"t":"edge","id":"e-rag-docs","from":"rag","to":"docs","label":"read"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Lets RAG service reach Model Studio over the internet."}
{"t":"edge","id":"e-rag-nat","from":"rag","to":"nat","kind":"control"}
{"t":"ask","id":"doc-volume","text":"How many documents will the agent cover?","options":["Under 1,000","1,000 to 50,000","Over 50,000"]}
{"t":"ask","id":"embedding-model","text":"Do you want hosted Qwen embeddings or a self-hosted embedding model on PAI-EAS?","options":["Hosted Qwen via Model Studio","Self-hosted on PAI-EAS"]}
{"t":"done","summary":"Document Q&A agent built with PAI-EAS as the RAG service, Milvus for vector search, OSS for documents and Model Studio for LLM answers."}

{"t":"say","text":"I'll draw a serverless coding agent on AgentRun with an isolated sandbox, no Kubernetes involved."}
{"t":"req","text":"We don't run Kubernetes and won't","avoid":["kubernetes","ack","acs"]}
{"t":"plan","products":["users","agentrun","agent-sandbox","model-studio","tablestore","sls"]}
{"t":"assume","id":"access","text":"Internal team access only","alt":"Public API access"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Developers","group":"internet","why":"Team members sending prompts to the agent."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"node","id":"agent","product":"agentrun","label":"Coding agent","group":"sg","why":"Serverless runtime hosting the code-first agent without Kubernetes."}
{"t":"edge","id":"e-users-agent","from":"users","to":"agent","label":"prompts"}
{"t":"node","id":"sandbox","product":"agent-sandbox","label":"Isolated sandbox","group":"sg","why":"Runs agent-written code in isolation safely."}
{"t":"edge","id":"e-agent-sandbox","from":"agent","to":"sandbox","label":"execute"}
{"t":"node","id":"llm","product":"model-studio","label":"Model Studio","group":"sg","why":"Provides Qwen models for the agent reasoning."}
{"t":"edge","id":"e-agent-llm","from":"agent","to":"llm","label":"inference"}
{"t":"node","id":"memory","product":"tablestore","label":"Agent memory","group":"sg","why":"Stores conversation history and agent state."}
{"t":"edge","id":"e-agent-memory","from":"agent","to":"memory","label":"state"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Captures agent traces and sandbox output."}
{"t":"edge","id":"e-agent-logs","from":"agent","to":"logs","kind":"control","label":"traces"}
{"t":"ask","id":"agent-framework","text":"Which agent framework or SDK are you building with?","options":["Custom Python or TypeScript","LangChain / LlamaIndex","Other"]}
{"t":"ask","id":"file-storage","text":"Does the agent need persistent file storage across sessions?","options":["Yes, add OSS","No, ephemeral is fine"]}
{"t":"done","summary":"Serverless coding agent on AgentRun with an isolated sandbox, Model Studio for inference, Tablestore for memory and SLS for traces in Singapore."}

{"t":"say","text":"ACS Agent Sandbox has no GPUs, so fine-tuning Qwen3-8B must run on PAI DLC instead."}
{"t":"plan","products":["pai-dsw","pai-dlc","pai-model-gallery","oss","cpfs"]}
{"t":"assume","id":"method","text":"Light SFT of supported Qwen via Model Studio","alt":"Full fine-tune keeping weights on PAI"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"node","id":"notebook","product":"pai-dsw","label":"Dev notebook","group":"sg","why":"Prepare datasets and launch training jobs."}
{"t":"node","id":"gallery","product":"pai-model-gallery","label":"Model Gallery","group":"sg","why":"No-code Qwen3-8B SFT config and one-click deploy."}
{"t":"edge","id":"e-notebook-gallery","from":"notebook","to":"gallery","kind":"control"}
{"t":"node","id":"training","product":"pai-dlc","label":"GPU training jobs","group":"sg","why":"Runs distributed Qwen3-8B fine-tuning on GPUs."}
{"t":"edge","id":"e-gallery-training","from":"gallery","to":"training","kind":"control","label":"launch"}
{"t":"node","id":"dataset","product":"oss","label":"Training data","group":"sg","why":"Stores input datasets and output checkpoints."}
{"t":"edge","id":"e-training-dataset","from":"training","to":"dataset","label":"read/write"}
{"t":"node","id":"scratch","product":"cpfs","label":"Scratch storage","group":"sg","why":"High-throughput shared FS for multi-node training."}
{"t":"edge","id":"e-training-scratch","from":"training","to":"scratch","label":"IO"}
{"t":"ask","id":"tune-depth","text":"Do you need full fine-tuning with weight export, or is light SFT via Model Studio enough?","options":["Light SFT (Model Studio)","Full fine-tune (PAI DLC)"]}
{"t":"ask","id":"serving","text":"Should I add a PAI EAS serving endpoint for the tuned model?","options":["Yes, add serving","No, training only"]}
{"t":"done","summary":"Qwen3-8B fine-tuning uses PAI DLC on GPUs because ACS Agent Sandbox provides no GPU capacity."}

{"t":"say","text":"I'll draw a multiplayer game backend with mobile clients, GA for low latency, NLB, ECS game servers, Tair and RDS."}
{"t":"plan","products":["mobile-app","dns","ga","nlb","ecs","tair","rds","oss","sls"]}
{"t":"assume","id":"game-type","text":"Real-time multiplayer requiring low latency","alt":"Turn-based or async multiplayer"}
{"t":"assume","id":"region","text":"Singapore region, global players via GA","alt":"Single-region players only"}
{"t":"assume","id":"scale","text":"Around 10k concurrent players at launch","alt":"Over 100k concurrent players"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"players","product":"mobile-app","label":"Mobile players","group":"internet","why":"Players connecting from iOS and Android devices."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves game domain to Global Accelerator."}
{"t":"edge","id":"e-players-dns","from":"players","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"ga","product":"ga","label":"Global Accelerator","group":"edge","why":"Routes player traffic over Alibaba backbone for low latency."}
{"t":"edge","id":"e-players-ga","from":"players","to":"ga","label":"TCP/UDP"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Game VPC","parent":"sg"}
{"t":"node","id":"nlb","product":"nlb","label":"NLB","group":"vpc","zones":["a","b"],"why":"Layer-4 load balancer handling high-throughput game connections."}
{"t":"edge","id":"e-ga-nlb","from":"ga","to":"nlb","label":"forward"}
{"t":"node","id":"game-servers","product":"ecs","label":"Game servers","group":"vpc","zones":["a","b"],"why":"Runs multiplayer game sessions across two zones."}
{"t":"edge","id":"e-nlb-game-servers","from":"nlb","to":"game-servers","label":"game traffic"}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Stores player sessions, leaderboards and real-time state."}
{"t":"edge","id":"e-game-servers-cache","from":"game-servers","to":"cache","label":"read/write"}
{"t":"node","id":"db","product":"rds","label":"Player DB","group":"vpc","zones":["a","b"],"why":"Persists player profiles, inventory and match history."}
{"t":"edge","id":"e-game-servers-db","from":"game-servers","to":"db","label":"SQL"}
{"t":"node","id":"assets","product":"oss","label":"Game assets","group":"sg","why":"Stores patches, maps and downloadable content."}
{"t":"edge","id":"e-game-servers-assets","from":"game-servers","to":"assets","label":"fetch"}
{"t":"node","id":"logs","product":"sls","label":"Game logs","group":"sg","why":"Centralizes server logs, telemetry and crash reports."}
{"t":"edge","id":"e-game-servers-logs","from":"game-servers","to":"logs","kind":"control"}
{"t":"ask","id":"game-protocol","text":"What protocol does your game use for real-time communication?","options":["TCP","UDP","WebSocket"]}
{"t":"ask","id":"matchmaking","text":"Do you need a dedicated matchmaking service or is it handled in the game servers?","options":["In game servers","Dedicated service"]}
{"t":"done","summary":"Mobile multiplayer backend with Global Accelerator, NLB, ECS game servers in two zones, Tair cache, RDS and OSS."}

{"t":"say","text":"I'll design a furniture e-commerce site in Singapore with ESA for fast Southeast Asia browsing, ALB, ECS, cache and database."}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","rds","oss","sls"]}
{"t":"assume","id":"exposure","text":"Public-facing shop","alt":"Internal only"}
{"t":"assume","id":"scale","text":"About 10k shoppers","alt":"Over 100k shoppers"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers","group":"internet","why":"Customers across Southeast Asia browsing handmade furniture."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the shop domain to ESA edge nodes."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches pages and furniture images close to SEA shoppers."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Shop VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Spreads traffic over both zones for availability."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Blocks injection attacks and bots before the app."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"Web servers","group":"vpc","zones":["a","b"],"why":"Runs the shop application in two zones."}
{"t":"node","id":"scaling","product":"ess","label":"Auto Scaling","group":"vpc","attachTo":"app","why":"Adds servers during sales or peak traffic."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Sessions go to Tair and orders to RDS, both with a standby in the second zone."}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Keeps carts and sessions fast."}
